{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 16,
      "text_ar": "الرَّبُّ يُهَدِّدُ، وَمَنْ لاَ يَنْكَسِرُ تَمَاماً إِلَى قِطَعٍ عِنْدَ وُجُودِهِ؟",
      "verse": 11
    },
    {
      "chapter": 16,
      "text_ar": "الأَرْضُ وَأَسَاسَاتُهَا تَرْتَجِفُ. الْبَحْرُ يَرْتَفِعُ بِأَمْوَاجٍ مِنَ الأَعْمَاقِ، وَأَمْوَاجُهُ تَتَكَدَّرُ، مَعَ السَّمَكِ الَّذِي فِيهَا، عِنْدَ حُضُورِ الرَّبِّ، وَأَمَامَ مَجْدِ قُوَّتِهِ.",
      "verse": 12
    },
    {
      "chapter": 16,
      "text_ar": "لأَنَّ يَمِينَهُ الَّتِي تَنْحَنِي بِالْقَوْسِ قَوِيَّةٌ، وَسِهَامَهُ الَّتِي يَرْمِيهَا حَادَّةٌ، وَلَنْ تُخْطِئَ عِنْدَمَا تَبْدَأُ فِي الإِطْلَاقِ إِلَى أَقْصَى أَرَاضِي الْعَالَمِ.",
      "verse": 13
    },
    {
      "chapter": 16,
      "text_ar": "هُوَذَا الْمَصَائِبُ قَدْ أُرْسِلَتْ، وَلَنْ تَرْجِعَ مَرَّةً أُخْرَى حَتَّى تَأْتِيَ عَلَى الأَرْضِ.",
      "verse": 14
    },
    {
      "chapter": 16,
      "text_ar": "النَّارُ اشْتَعَلَتْ وَلَنْ تُطْفَأَ حَتَّى تَأْكُلَ أَسَاسَاتِ الأَرْضِ.",
      "verse": 15
    },
    {
      "chapter": 16,
      "text_ar": "كَمَا أَنَّ السَّهْمَ الَّذِي يَرْمِيهِ رَامٍ قَوِيٌّ لاَ يَرْجِعُ إِلَى الْوَرَاءِ، هَكَذَا الْمَصَائِبُ الَّتِي أُرْسِلَتْ عَلَى الأَرْضِ لَنْ تَرْجِعَ مَرَّةً أُخْرَى.",
      "verse": 16
    },
    {
      "chapter": 16,
      "text_ar": "وَيْلٌ لِي! وَيْلٌ لِي! مَنْ يُخَلِّصُنِي فِي تِلْكَ الأَيَّامِ؟",
      "verse": 17
    },
    {
      "chapter": 16,
      "text_ar": "بِدَايَةُ الأَحْزَانِ، عِنْدَمَا يَكُونُ هُنَاكَ نَوْحٌ عَظِيمٌ؛ بِدَايَةُ الْجُوعِ، وَكَثِيرُونَ سَيَهْلِكُونَ؛ بِدَايَةُ الْحُرُوبِ، وَالسَّلَطَاتُ سَتَقِفُ فِي خَوْفٍ؛ بِدَايَةُ الْمَصَائِبِ، وَالْجَمِيعُ سَيَرْتَجِفُونَ! مَاذَا سَيَفْعَلُونَ عِنْدَمَا تَأْتِي الْمَصَائِبُ؟",
      "verse": 18
    },
    {
      "chapter": 16,
      "text_ar": "هُوَذَا جُوعٌ وَوَبَأٌ، أَلَمٌ وَضِيقٌ! إِنَّهَا تُرْسَلُ كَأَسْوِطَةٍ لِلتَّأْدِيبِ.",
      "verse": 19
    },
    {
      "chapter": 16,
      "text_ar": "وَلَكِنْ لِكُلِّ هَذِهِ الأُمُورِ لَنْ يَرُدُّوا أَنْفُسَهُمْ عَنْ شَرِّهِمْ، وَلَنْ يَذْكُرُوا الأَسْوِطَةَ دَائِماً.",
      "verse": 20
    }
  ]
}
